import json,hashlib,pathlib,subprocess,re,datetime
P=pathlib.Path('docs/content-audits/question-quality-wave-7/process-v2-weather20');R=P/'reviewer'
def canon(x):return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
def sha(x):return hashlib.sha256(canon(x)).hexdigest()
def load(p):return json.load(open(p))
def save(n,x):(R/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
